const crypto = require('crypto');

const secret = $env.YASMINA_N8N_HMAC_SECRET;
if (!secret) throw new Error('YASMINA_N8N_HMAC_SECRET is not configured');

const raw = Buffer.isBuffer($json.body)
  ? $json.body.toString('utf8')
  : (typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body));
const envelope = JSON.parse(raw);
const timestamp = String($json.headers['x-yasmina-timestamp'] ?? '');
const provided = String($json.headers['x-yasmina-signature'] ?? '');
if (!timestamp || !provided) throw new Error('missing Yasmina HMAC headers');

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.').update(raw).digest('hex');
const expectedBuffer = Buffer.from(expected);
const providedBuffer = Buffer.from(provided);
if (expectedBuffer.length !== providedBuffer.length || !crypto.timingSafeEqual(expectedBuffer, providedBuffer)) {
  throw new Error('invalid Yasmina HMAC signature');
}
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) {
  throw new Error('Yasmina timestamp is outside the replay window');
}
if (envelope.event_type !== 'rfq.dispatch' || !envelope.callback_url || !envelope.tender?.items?.length) {
  throw new Error('invalid RFQ envelope');
}

// Replace this fixed price with your supplier-quote extraction/mapping logic.
const unitPrice = '10.0000';
const items = envelope.tender.items;
const total = items.reduce((sum, item) => sum + Number(item.quantity) * Number(unitPrice), 0);
const supplier = envelope.suppliers[0];
const quote = {
  supplier_name: supplier?.name ?? 'n8n supplier',
  supplier_contact_email: supplier?.email ?? null,
  quote_reference: 'N8N-' + String(envelope.event_id).slice(0, 8),
  tender_id: envelope.tender.tender_id,
  currency: envelope.tender.currency,
  valid_until: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10),
  payment_terms: 'Net 30',
  incoterms: 'DAP',
  delivery_days: 2,
  total_net: total.toFixed(2),
  raw_extraction: { source: 'n8n' },
  lines: items.map((item, index) => ({
    line_number: index + 1,
    description: item.description,
    tender_item_id: item.tender_item_id,
    quantity: item.quantity,
    unit: item.unit,
    unit_price_net: unitPrice,
    delivery_days: 2,
  })),
};

const body = JSON.stringify({ event_id: envelope.event_id, quotes: [quote] });
const callbackTimestamp = Math.floor(Date.now() / 1000);
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(callbackTimestamp + '.').update(body).digest('hex');

return [{
  json: {
    callback_url: envelope.callback_url,
    body,
    idempotency_key: 'n8n-quote-' + envelope.event_id,
    timestamp: callbackTimestamp,
    signature,
    quote_reference: quote.quote_reference,
  },
}];
